import "@stdlib/exotic-cells"
import "@stdlib/gas-payments"
import "@stdlib/lisp-lists"
import "config-helpers"
import "errors"
import "messages"
import "storage"

contract Config {
    author: "The Tolk Team"
    version: "1.0.0"
    description: "TON Config contract. Manages network configuration parameters"
    incomingMessages: AllowedInternalMessage
    storage: Storage
}

type AllowedInternalMessage =
    | SetNextValidatorSetRequest
    | SetCustomParamRequest
    | NewVotingProposalRequest
    | VoteForProposalRequest

fun onInternalMessage(in: InMessage) {
    val isAdminOfCustomParam = in.senderAddress == ADMIN_ADDRESS_FOR_CUSTOM_PARAMS;
    val isValidWorkchain = isAdminOfCustomParam || in.senderAddress.getWorkchain() == MASTERCHAIN;

    if (!isValidWorkchain || in.body.isEmpty()) {
        return;
    }

    val tag = in.body.preloadUint(32);
    if (isAdminOfCustomParam && tag != OP_SET_CUSTOM_PARAM) {
        throw ERROR_INVALID_MESSAGE;
    }

    if (tag == 0 || (tag & INTERNAL_QUERY_HIGH_BIT) != 0) {
        return;
    }

    val msg = lazy AllowedInternalMessage.fromSlice(
        in.body,
        { throwIfOpcodeDoesNotMatch: ERROR_INVALID_MESSAGE },
    );

    match (msg) {
        SetNextValidatorSetRequest => {
            val electorParam = blockchain.configParam(CONFIG_PARAM_ELECTOR_ADDRESS);
            var ok = false;

            if (electorParam != null) {
                val (_, srcHash) = in.senderAddress.getWorkchainAndHash();
                val electorHash = electorParam!.beginParse().preloadUint(256);

                if (srcHash == electorHash) {
                    val validatorSetWindow = checkValidatorSet(msg.vset);
                    val now = blockchain.now();
                    ok = (validatorSetWindow.utimeSince > now) &&
                    (validatorSetWindow.utimeUntil > validatorSetWindow.utimeSince);
                }
            }

            if (ok) {
                Storage.setConfigParam(CONFIG_PARAM_NEXT_VALIDATOR_SET, msg.vset);
                sendConfirmation(in.senderAddress, msg.queryId, TAG_SET_NEXT_VALIDATORS_ACCEPTED);
            } else {
                sendError(in.senderAddress, msg.queryId, TAG_SET_NEXT_VALIDATORS_REJECTED);
            }
        }

        SetCustomParamRequest => {
            val (_, isExotic) = msg.value.beginParseSpecial();
            val isCustomParam = msg.paramId == CUSTOM_PARAM_1 || msg.paramId == CUSTOM_PARAM_2;

            if (!isExotic && msg.value.depth() == 0 && isCustomParam && isAdminOfCustomParam) {
                Storage.setConfigParam(msg.paramId, msg.value);
                sendConfirmation(msg.receiverAddress, msg.queryId, TAG_SET_CUSTOM_PARAM_ACCEPTED);
            } else {
                sendError(msg.receiverAddress, msg.queryId, TAG_SET_CUSTOM_PARAM_REJECTED);
            }
        }

        NewVotingProposalRequest => {
            val price = registerVotingProposal(msg, in.valueCoins);

            var mode = SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE;
            var ansTag = -price;

            if (price >= 0) {
                reserveToncoinsOnBalance(price, RESERVE_MODE_INCREASE_BY_ORIGINAL_BALANCE);

                ansTag = TAG_NEW_VOTING_CREATED;
                mode = SEND_MODE_CARRY_ALL_BALANCE;
            }

            val answerMsg = createMessage({
                bounce: true,
                dest: in.senderAddress,
                value: 0,
                body: AnswerBody {
                    ansTag: (ansTag & 0xffffffff),
                    queryId: msg.queryId,
                },
            });

            answerMsg.send(mode);
        }

        VoteForProposalRequest => {
            val signedVote = msg.loadSignedVotePayload(ERROR_INVALID_MESSAGE);
            val validatorContext = getCurrentValidatorContext(signedVote.validatorIndex);

            assert (
                isSliceSignatureValid(
                    msg.signedVoteBody,
                    msg.signature as slice,
                    validatorContext.publicKey,
                )
            ) throw ERROR_INVALID_SIGNATURE;

            val result = proceedRegisterVote(
                signedVote.proposalHash,
                signedVote.validatorIndex,
                validatorContext.weight,
                validatorContext.validatorSetId,
                validatorContext.totalWeight,
            );
            sendConfirmation(in.senderAddress, msg.queryId, TAG_VOTE_PROCESSED_BASE + result);
        }

        else => throw ERROR_INVALID_MESSAGE,
    }
}

fun onExternalMessage(inMsgBody: slice) {
    assert (inMsgBody.depth() <= 128) throw ERROR_EXTERNAL_BODY_TOO_DEEP;

    val msg = lazy ExternalSignedMessage.fromSlice(inMsgBody, { throwIfOpcodeDoesNotMatch: 0 });

    assert (msg.action.validUntil >= blockchain.now()) throw ERROR_VALID_UNTIL_EXPIRED;

    var storage = lazy Storage.load();
    assert (msg.action.msgSeqno == storage.storedSeqno) throw ERROR_BAD_SEQNO;

    val validatorContext = getCurrentValidatorContext(msg.action.validatorIndex);

    assert (
        isSliceSignatureValid(
            inMsgBody.skipBits(512),
            msg.signature as slice,
            validatorContext.publicKey,
        )
    ) throw ERROR_INVALID_SIGNATURE;

    acceptExternalMessage();

    storage.incrementSeqno();
    storage.save();
    commitContractDataAndActions();

    proceedRegisterVote(
        msg.action.proposalHash,
        msg.action.validatorIndex,
        validatorContext.weight,
        validatorContext.validatorSetId,
        validatorContext.totalWeight,
    );
}

fun onRunTickTock() {
    var storage = lazy Storage.load();
    var configDict = storage.config;
    var updated = false;

    val nextVset = configDict.getById(CONFIG_PARAM_NEXT_VALIDATOR_SET);
    if (nextVset != null) {
        var ds = nextVset!.beginParse();
        if (ds.remainingBitsCount() >= 40) {
            val tag = ds.loadUint(8);
            val since = ds.preloadUint(32);

            if (since <= blockchain.now() && tag == OP_VALIDATOR_SET_EXT) {
                val oldCurrentVset = configDict.setByIdAndGetPrevious(
                    CONFIG_PARAM_CURRENT_VALIDATOR_SET,
                    nextVset!,
                );

                if (oldCurrentVset != null) {
                    configDict.setById(CONFIG_PARAM_PREVIOUS_VALIDATOR_SET, oldCurrentVset!);
                } else {
                    configDict.deleteById(CONFIG_PARAM_PREVIOUS_VALIDATOR_SET);
                }

                configDict.deleteById(CONFIG_PARAM_NEXT_VALIDATOR_SET);
                updated = true;
            }
        }
    }

    if (!updated) {
        scanRandomProposal(mutate storage.voteDict);
    }

    storage.config = configDict;
    storage.save();
}

get fun seqno(): int {
    val storage = lazy Storage.load();
    return storage.storedSeqno;
}

struct ProposalParameterView {
    paramId: int32
    paramValue: cell?
    paramHash: int
}

struct ProposalView {
    expires: uint32
    isCritical: bool
    proposal: ProposalParameterView
    validatorSetId: uint256
    voters: lisp_list<int>
    remainingWeight: int64
    roundsRemaining: uint8
    wins: uint8
    losses: uint8
}

struct ProposalListEntry {
    proposalHash: uint256
    proposal: ProposalView
}

fun unpackProposal(statusSlice: slice): ProposalView {
    val status = ConfigProposalStatus.fromSlice(
        statusSlice,
        { throwIfOpcodeDoesNotMatch: ERROR_INVALID_PROPOSAL_STATUS },
    );
    val proposal = status.proposal.load();

    var votersList = [] as lisp_list<int>;
    var voter = status.voters.findLast();
    while (voter.isFound) {
        votersList.prependHead(voter.getKey());
        voter = status.voters.iteratePrev(voter);
    }

    val paramHash = proposal.ifHashEqual == null ? -1 : (proposal.ifHashEqual! as int);

    return ProposalView {
        expires: status.expires,
        isCritical: status.isCritical,
        proposal: ProposalParameterView {
            paramId: proposal.paramId,
            paramValue: proposal.paramValue,
            paramHash,
        },
        validatorSetId: status.validatorSetId,
        voters: votersList,
        remainingWeight: status.remainingWeight,
        roundsRemaining: status.roundsRemaining,
        wins: status.wins,
        losses: status.losses,
    };
}

fun proposalParameterViewToTuple(proposal: ProposalParameterView): tuple {
    return [proposal.paramId, proposal.paramValue, proposal.paramHash];
}

fun proposalViewToTuple(proposal: ProposalView): tuple {
    return [
        proposal.expires,
        proposal.isCritical,
        proposalParameterViewToTuple(proposal.proposal),
        proposal.validatorSetId,
        proposal.voters,
        proposal.remainingWeight,
        proposal.roundsRemaining,
        proposal.wins,
        proposal.losses,
    ];
}

get fun get_proposal(proposalHash: int): tuple? {
    val storage = lazy Storage.load();
    val lookup = storage.voteDict.get(proposalHash);
    if (!lookup.isFound) {
        return null;
    }
    return proposalViewToTuple(unpackProposal(lookup.loadValue()));
}

get fun list_proposals(): lisp_list<tuple> {
    val storage = lazy Storage.load();

    var list = [] as lisp_list<tuple>;
    var entry = storage.voteDict.findLast();
    while (entry.isFound) {
        list.prependHead([entry.getKey(), proposalViewToTuple(unpackProposal(entry.loadValue()))]);
        entry = storage.voteDict.iteratePrev(entry);
    }

    return list;
}

get fun proposal_storage_price(critical: int, seconds: int, bits: int, refs: int): int {
    val storage = lazy Storage.load();
    val configDict = storage.config;

    val cparam11 = configDict.getById(CONFIG_PARAM_VOTING_SETUP);
    assert (cparam11 != null) throw ERROR_INVALID_PROPOSAL_STATUS;

    val voteCfg = getVoteConfigInternal(critical != 0, cparam11!);
    if (seconds < voteCfg.minStoreSec) {
        return -1;
    }

    seconds = min(seconds, voteCfg.maxStoreSec);
    return voteCfg.calculateStoragePrice(seconds, bits, refs);
}

import "@stdlib/tvm-lowlevel"
import "errors"
import "messages"
import "storage"

fun getVoteConfigInternal(critical: bool, configParam11: cell): ConfigProposalSetup {
    val setup = ConfigVotingSetup.fromCell(
        configParam11,
        { throwIfOpcodeDoesNotMatch: ERROR_INVALID_PROPOSAL_STATUS },
    );

    return setup.selectProposalSetup(critical);
}

fun getVoteConfig(isCritical: bool): ConfigProposalSetup {
    val configParam11 = blockchain.configParam(CONFIG_PARAM_VOTING_SETUP);
    assert (configParam11 != null) throw ERROR_INVALID_PROPOSAL_STATUS;

    return getVoteConfigInternal(isCritical, configParam11);
}

fun getVoteRoundRulesInternal(critical: bool, configParam11: cell): ConfigProposalRoundRules {
    val setup = ConfigVotingSetup.fromCell(
        configParam11,
        { throwIfOpcodeDoesNotMatch: ERROR_INVALID_PROPOSAL_STATUS },
    );

    return ConfigProposalRoundRules.fromCell(
        critical ? setup.criticalParams : setup.normalParams,
        { throwIfOpcodeDoesNotMatch: ERROR_INVALID_PROPOSAL_STATUS },
    );
}

fun getVoteRoundRules(isCritical: bool): ConfigProposalRoundRules {
    val configParam11 = blockchain.configParam(CONFIG_PARAM_VOTING_SETUP);
    assert (configParam11 != null) throw ERROR_INVALID_PROPOSAL_STATUS;

    return getVoteRoundRulesInternal(isCritical, configParam11);
}

struct ValidatorSetWindow {
    utimeSince: int
    utimeUntil: int
}

fun checkValidatorSet(validatorSet: cell): ValidatorSetWindow {
    val parsed = ValidatorSetMeta.fromCell(
        validatorSet,
        { throwIfOpcodeDoesNotMatch: ERROR_INVALID_VALIDATOR_SET },
    );

    assert (parsed.main > 0) throw ERROR_INVALID_VALIDATOR_SET;
    assert (parsed.total >= parsed.main) throw ERROR_INVALID_VALIDATOR_SET;

    return { utimeSince: parsed.utimeSince, utimeUntil: parsed.utimeUntil };
}

fun sendConfirmation(addr: address, queryId: uint64, ansTag: int) {
    val confirmMsg = createMessage({
        bounce: true,
        dest: addr,
        value: 0,
        body: AnswerBody {
            ansTag: (ansTag & 0xffffffff),
            queryId,
        },
    });

    confirmMsg.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE);
}

fun sendError(addr: address, queryId: uint64, ansTag: int) {
    val rejectMsg = createMessage({
        bounce: true,
        dest: addr,
        value: 0,
        body: AnswerBody {
            ansTag: (ansTag & 0xffffffff),
            queryId,
        },
    });

    rejectMsg.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE);
}

fun changeElectorCode(codeBody: slice) {
    val electorParam = blockchain.configParam(CONFIG_PARAM_ELECTOR_ADDRESS);
    assert (electorParam != null) throw ERROR_INVALID_MESSAGE;

    val electorAddrHash = electorParam.beginParse().preloadUint(256);
    val queryId = blockchain.now();

    val actionMsg = createMessage({
        bounce: true,
        dest: (MASTERCHAIN, electorAddrHash),
        value: MIN_INTERNAL_MESSAGE_VALUE,
        body: ElectorCodeChangeAction {
            queryId,
            payload: codeBody,
        },
    });

    actionMsg.send(SEND_MODE_REGULAR);
}

// get method to keep the function
@method_id(1666)
fun afterCodeUpgrade(_param: slice, _oldCode: continuation) {}

fun applyCodeUpgrade(newCode: cell, upgradeParams: slice): never {
    contract.setCodePostponed(newCode);

    val oldCode = getTvmRegisterC3();

    // SAFETY: BLESS + execute
    setTvmRegisterC3(transformSliceToContinuation(newCode.beginParse()));
    afterCodeUpgrade(upgradeParams, oldCode);
    throw 0;
}

struct CurrentValidatorSetMeta {
    validatorSetId: uint256
    totalWeight: int
}

fun getCurrentValidatorSetMeta(): CurrentValidatorSetMeta {
    val validatorSet = blockchain.configParam(CONFIG_PARAM_CURRENT_VALIDATOR_SET);
    assert (validatorSet != null) throw ERROR_WRONG_CURRENT_VSET;

    val parsed = ValidatorSetMeta.fromCell(
        validatorSet,
        { throwIfOpcodeDoesNotMatch: ERROR_WRONG_CURRENT_VSET },
    );

    return { validatorSetId: validatorSet.hash(), totalWeight: parsed.totalWeight };
}

struct ValidatorKeyAndWeight {
    publicKey: int
    weight: int
}

struct CurrentValidatorContext {
    validatorSetId: uint256
    totalWeight: int
    publicKey: int
    weight: int
}

fun unpackValidatorDescr(validatorDescription: slice): ValidatorKeyAndWeight {
    val descr = lazy ValidatorDescr.fromSlice(validatorDescription);

    match (descr) {
        ValidatorDescrSimple => {
            assert (descr.pubkeyTag == OP_ED25519_PUBKEY) throw ERROR_WRONG_VALIDATOR_DESCRIPTION;
            return { publicKey: descr.publicKey, weight: descr.weight };
        }
        ValidatorDescrWithAdnl => {
            assert (descr.pubkeyTag == OP_ED25519_PUBKEY) throw ERROR_WRONG_VALIDATOR_DESCRIPTION;
            return { publicKey: descr.publicKey, weight: descr.weight };
        }

        else => throw ERROR_WRONG_VALIDATOR_DESCRIPTION,
    }
}

fun getCurrentValidatorContext(idx: uint16): CurrentValidatorContext {
    val validatorSet = blockchain.configParam(CONFIG_PARAM_CURRENT_VALIDATOR_SET);
    assert (validatorSet != null) throw ERROR_WRONG_CURRENT_VSET;

    val parsed = ValidatorSetExt.fromCell(
        validatorSet,
        { throwIfOpcodeDoesNotMatch: ERROR_WRONG_CURRENT_VSET },
    );
    val validators = createMapFromLowLevelDict<uint16, slice>(parsed.validators);
    val lookup = validators.get(idx);

    assert (lookup.isFound) throw ERROR_WRONG_VALIDATOR_DESCRIPTION;

    val validatorInfo = unpackValidatorDescr(lookup.loadValue());
    return {
        validatorSetId: validatorSet.hash(),
        totalWeight: parsed.totalWeight,
        publicKey: validatorInfo.publicKey,
        weight: validatorInfo.weight,
    };
}

struct ProposalAcceptanceResult {
    paramId: int
    paramVal: cell?
}

@inline_ref
fun acceptProposal(
    mutate configDict: ConfigDict,
    proposalCell: Cell<ConfigProposal>,
    isCritical: bool,
): ProposalAcceptanceResult {
    val proposal = proposalCell.load();
    val paramId = proposal.paramId;

    val currentValue = configDict.getById(paramId);
    val currentHash: uint256 = currentValue == null ? 0 : currentValue.hash();

    // current value has incorrect hash, do not apply changes
    if (proposal.ifHashEqual != null && currentHash != proposal.ifHashEqual) {
        return { paramId: 0, paramVal: null };
    }

    // custom parameters cannot be changed by validator voting, do not apply changes
    if (paramId == CUSTOM_PARAM_1 || paramId == CUSTOM_PARAM_2) {
        return { paramId: 0, paramVal: null };
    }

    val mandatoryParamsCell = configDict.getById(CONFIG_PARAM_MANDATORY_PARAMS);

    if (mandatoryParamsCell != null && proposal.paramValue == null) {
        val mandatoryParams = createMapFromLowLevelDict<int32, slice>(mandatoryParamsCell);

        // cannot set a mandatory parameter to null
        if (mandatoryParams.exists(paramId)) {
            return { paramId: 0, paramVal: null };
        }
    }

    val criticalParamsCell = configDict.getById(CONFIG_PARAM_CRITICAL_PARAMS);

    if (criticalParamsCell != null) {
        val criticalParams = createMapFromLowLevelDict<int32, slice>(criticalParamsCell);

        // trying to set a critical parameter after a non-critical voting
        if (criticalParams.exists(paramId) && !isCritical) {
            return { paramId: 0, paramVal: null };
        }
    }

    // CHANGE ONE CONFIGURATION PARAMETER
    if (proposal.paramValue == null) {
        configDict.delete(paramId);
    } else {
        configDict.set(paramId, proposal.paramValue!);
    }

    return { paramId, paramVal: proposal.paramValue };
}

@inline_ref
fun performProposedAction(publicKey: int, paramId: int, paramVal: cell?): uint256 {
    // appoint or depose dictator
    if (paramId == -999) {
        return paramVal == null ? 0 : paramVal.beginParse().preloadUint(256);
    }

    if (paramVal == null) {
        return publicKey;
    }

    // upgrade code
    if (paramId == -1000) {
        var cs = paramVal.beginParse();

        val newCode = cs.loadRef();
        applyCodeUpgrade(newCode, cs);
    }

    // update elector code
    if (paramId == -1001) {
        changeElectorCode(paramVal.beginParse());
    }

    return publicKey;
}

@inline_ref
fun updateProposalStatus(
    status: ConfigProposalStatus,
    previousWeightRemaining: int,
): ConfigProposalStatus? {
    val voteRules = getVoteRoundRules(status.isCritical);

    if (previousWeightRemaining >= 0) {
        status.losses += 1;
    }
    if (status.losses > voteRules.maxLosses) {
        return null;
    }

    status.roundsRemaining -= 1;
    if (status.roundsRemaining < 0) {
        return null;
    }

    return status;
}

struct VoteRegistrationResult {
    acceptedProposal: Cell<ConfigProposal>?
    status: int
}

@inline_ref
fun registerVote(
    mutate voteDict: VoteDict,
    proposalHash: uint256,
    idx: uint16,
    weight: int,
    currentValidatorSetId: uint256,
    currentTotalWeight: int,
): VoteRegistrationResult {
    val statusLookup = voteDict.get(proposalHash);

    // config proposal not found
    if (!statusLookup.isFound) {
        return { acceptedProposal: null, status: -1 };
    }

    var status = ConfigProposalStatus.fromSlice(
        statusLookup.loadValue(),
        { throwIfOpcodeDoesNotMatch: ERROR_INVALID_PROPOSAL_STATUS },
    );

    // config proposal expired, delete and report not found
    if (status.expires <= blockchain.now()) {
        voteDict.delete(proposalHash);

        return { acceptedProposal: null, status: -1 };
    }

    // config proposal belongs to a previous validator set
    if (status.validatorSetId != currentValidatorSetId) {
        val updated = updateProposalStatus(status, status.remainingWeight);

        // discard proposal (existed for too many rounds, or too many losses)
        if (updated == null) {
            voteDict.delete(proposalHash);
            return { acceptedProposal: null, status: -1 };
        }

        status = updated;
        status.validatorSetId = currentValidatorSetId;
        status.voters = [];

        status.remainingWeight = mulDivFloor(
            currentTotalWeight,
            VOTE_WEIGHT_THRESHOLD_NUMERATOR,
            VOTE_WEIGHT_THRESHOLD_DENOMINATOR,
        );
    }

    // already voted for this proposal, ignore vote
    if (status.voters.exists(idx)) {
        return { acceptedProposal: null, status: -2 };
    }

    // register vote
    status.voters.set(idx, blockchain.now());

    val oldWeightRemaining = status.remainingWeight;
    status.remainingWeight -= weight;

    // not enough votes, or proposal already accepted in this round
    // simply update remainingWeight
    if ((status.remainingWeight ^ oldWeightRemaining) >= 0) {
        voteDict.set(proposalHash, status.toCell().beginParse());

        return { acceptedProposal: null, status: 2 };
    }

    // proposal wins in this round
    val voteRules = getVoteRoundRules(status.isCritical);
    var wins = status.wins;

    wins += 1;

    // proposal is accepted, remove and process
    if (wins >= voteRules.minWins) {
        voteDict.delete(proposalHash);

        return { acceptedProposal: status.proposal, status: status.isCritical ? 7 : 6 };
    }

    status.wins = wins;
    voteDict.set(proposalHash, status.toCell().beginParse());

    return { acceptedProposal: null, status: 2 };
}

fun Storage.incrementSeqno(mutate self) {
    self.storedSeqno = ((self.storedSeqno + 1) % EXTERNAL_SEQNO_MODULO);
}

@inline_ref
fun proceedRegisterVote(
    proposalHash: uint256,
    idx: uint16,
    weight: int,
    currentValidatorSetId: uint256,
    currentTotalWeight: int,
): int {
    var storage = lazy Storage.load();

    var voteDict = storage.voteDict;
    var acceptedProposal: Cell<ConfigProposal>? = null;

    var status = 0;

    val voteRegistration = registerVote(
        mutate voteDict,
        proposalHash,
        idx,
        weight,
        currentValidatorSetId,
        currentTotalWeight,
    );

    acceptedProposal = voteRegistration.acceptedProposal;
    status = voteRegistration.status;
    storage.voteDict = voteDict;

    storage.save();

    if (acceptedProposal != null) {
        val isCritical = status == 7;

        var configDict = storage.config;
        var paramId = 0;
        var paramVal: cell? = null;

        val proposalAcceptance = acceptProposal(mutate configDict, acceptedProposal!, isCritical);

        paramId = proposalAcceptance.paramId;
        paramVal = proposalAcceptance.paramVal;

        storage.config = configDict;
        storage.save();

        // 0 == not accepted
        if (paramId != 0) {
            commitContractDataAndActions();

            val publicKey = performProposedAction(storage.publicKey, paramId, paramVal);

            storage.publicKey = publicKey;
            storage.save();
        }
    }

    return status;
}

struct ProposalScanResult {
    proposalStatusSlice: slice?
    changed: bool
}

@inline_ref
fun scanProposal(statusSlice: slice): ProposalScanResult {
    val currentValidatorSet = getCurrentValidatorSetMeta();
    val curVsetId = currentValidatorSet.validatorSetId;

    var status = ConfigProposalStatus.fromSlice(
        statusSlice,
        { throwIfOpcodeDoesNotMatch: ERROR_INVALID_PROPOSAL_STATUS },
    );

    if (status.expires <= blockchain.now()) {
        return { proposalStatusSlice: null, changed: true };
    }

    if (status.validatorSetId == curVsetId) {
        return { proposalStatusSlice: statusSlice, changed: false };
    }

    val updated = updateProposalStatus(status, status.remainingWeight);
    if (updated == null) {
        return { proposalStatusSlice: null, changed: true };
    }

    status = updated!;
    status.validatorSetId = curVsetId;
    status.voters = [];

    status.remainingWeight = mulDivFloor(
        currentValidatorSet.totalWeight,
        VOTE_WEIGHT_THRESHOLD_NUMERATOR,
        VOTE_WEIGHT_THRESHOLD_DENOMINATOR,
    );

    return { proposalStatusSlice: status.toCell().beginParse(), changed: true };
}

fun scanRandomProposal(mutate voteDict: VoteDict) {
    if (voteDict.isEmpty()) {
        return;
    }

    random.initialize();
    val entry = voteDict.findKeyGreaterOrEqual(random.uint256());
    if (!entry.isFound) {
        return;
    }

    val proposalHash = entry.getKey();

    var proposalStatusSlice: slice? = null;
    var changed = false;

    val scanResult = scanProposal(entry.loadValue());

    proposalStatusSlice = scanResult.proposalStatusSlice;
    changed = scanResult.changed;

    if (changed) {
        if (proposalStatusSlice == null) {
            voteDict.delete(proposalHash);
        } else {
            voteDict.set(proposalHash, proposalStatusSlice!);
        }
    }
}

@inline_ref
fun registerVotingProposal(msg: NewVotingProposalRequest, msgValue: coins): int {
    var expireAt = msg.expireAt;

    if ((expireAt >> 30) != 0) {
        expireAt -= blockchain.now();
    }

    val proposal = msg.proposal.load();
    val paramId = proposal.paramId;

    if (paramId == CUSTOM_PARAM_1 || paramId == CUSTOM_PARAM_2) {
        return ERROR_TAG_CUSTOM_SLOT_VOTING_REJECTED;
    }

    var expectedHash: int = proposal.ifHashEqual == null ? -1 : proposal.ifHashEqual;

    if (expectedHash >= 0) {
        val curVal = blockchain.configParam(paramId);

        val curHash: uint256 = curVal == null ? 0 : curVal.hash();

        if (curHash != expectedHash) {
            expectedHash = ERROR_TAG_BAD_CURRENT_VALUE_HASH;
        }
    } else {
        val mandatoryParams = blockchain.configParam(CONFIG_PARAM_MANDATORY_PARAMS);

        if (mandatoryParams != null) {
            val mandatoryMap = createMapFromLowLevelDict<int32, slice>(mandatoryParams);

            if (mandatoryMap.exists(paramId)) {
                expectedHash = ERROR_TAG_MANDATORY_PARAM_CANNOT_BE_NULL;
            }
        }
    }

    if (proposal.paramValue != null && proposal.paramValue.depth() >= 256) {
        expectedHash = ERROR_TAG_BAD_VALUE;
    }

    if (expectedHash < -1) {
        return expectedHash;
    }

    if (!msg.critical) {
        val criticalParams = blockchain.configParam(CONFIG_PARAM_CRITICAL_PARAMS);

        if (criticalParams != null) {
            val criticalMap = createMapFromLowLevelDict<int32, slice>(criticalParams);

            if (criticalMap.exists(paramId)) {
                expectedHash = ERROR_TAG_CRITICAL_FLAG_REQUIRED;
            }
        }
    }

    if (expectedHash < -1) {
        return expectedHash;
    }

    val voteCfg = getVoteConfig(msg.critical);

    if (expireAt < voteCfg.minStoreSec) {
        return ERROR_TAG_PROPOSAL_EXPIRED;
    }
    expireAt = min(expireAt, voteCfg.maxStoreSec);

    var bits = 0;
    var refs = 0;

    if (proposal.paramValue != null) {
        (_, bits, refs) = proposal.paramValue!.calculateSizeStrict(PROPOSAL_BITS_OVERHEAD);
    }

    val pricePerSecond = voteCfg.calculateStoragePrice(1, bits, refs);
    var price = pricePerSecond * expireAt;

    expireAt += blockchain.now();

    var storage = lazy Storage.load();

    var voteDict = storage.voteDict;
    val proposalHash = msg.proposal.hash();

    val existing = voteDict.get(proposalHash);

    if (existing.isFound) {
        var status = ConfigProposalStatus.fromSlice(
            existing.loadValue(),
            { throwIfOpcodeDoesNotMatch: ERROR_INVALID_PROPOSAL_STATUS },
        );

        if (status.isCritical != msg.critical) {
            return ERROR_TAG_CANNOT_DOWNGRADE_CRITICALITY;
        }
        if (status.expires >= expireAt) {
            return ERROR_TAG_PROPOSAL_ALREADY_EXISTS;
        }

        price = pricePerSecond * (expireAt - status.expires + PROPOSAL_EXTENSION_GRACE_PERIOD);

        if (msgValue - price < MIN_INTERNAL_MESSAGE_VALUE) {
            return ERROR_TAG_NOT_ENOUGH_FUNDS;
        }

        status.expires = expireAt;
        voteDict.set(proposalHash, status.toCell().beginParse());

        storage.voteDict = voteDict;
        storage.save();

        return price;
    }

    if (msgValue - price < MIN_INTERNAL_MESSAGE_VALUE) {
        return ERROR_TAG_NOT_ENOUGH_FUNDS;
    }

    val currentValidatorSet = getCurrentValidatorSetMeta();

    val weightRemaining = mulDivFloor(
        currentValidatorSet.totalWeight,
        VOTE_WEIGHT_THRESHOLD_NUMERATOR,
        VOTE_WEIGHT_THRESHOLD_DENOMINATOR,
    );

    voteDict.set(
        proposalHash,
        ConfigProposalStatus {
            expires: expireAt,
            proposal: msg.proposal,
            isCritical: msg.critical,
            voters: [],
            remainingWeight: weightRemaining,
            validatorSetId: currentValidatorSet.validatorSetId,
            roundsRemaining: voteCfg.maxTotalRounds,
            wins: 0,
            losses: 0,
        }.toCell()
            .beginParse(),
    );

    storage.voteDict = voteDict;
    storage.save();

    return price;
}

